    export namespace v1alpha {
        /**
         * Specifies the audit configuration for a service. The configuration determines which permission types are logged, and what identities, if any, are exempted from logging. An AuditConfig must have one or more AuditLogConfigs.If there are AuditConfigs for both allServices and a specific service, the union of the two AuditConfigs is used for that service: the log_types specified in each AuditConfig are enabled, and the exempted_members in each AuditLogConfig are exempted.Example Policy with multiple AuditConfigs: { "audit_configs": [ { "service": "allServices", "audit_log_configs": [ { "log_type": "DATA_READ", "exempted_members": [ "user:jose@example.com" ] }, { "log_type": "DATA_WRITE" }, { "log_type": "ADMIN_READ" } ] }, { "service": "sampleservice.googleapis.com", "audit_log_configs": [ { "log_type": "DATA_READ" }, { "log_type": "DATA_WRITE", "exempted_members": [ "user:aliya@example.com" ] } ] } ] } For sampleservice, this policy enables DATA_READ, DATA_WRITE and ADMIN_READ logging. It also exempts jose@example.com from DATA_READ logging, and aliya@example.com from DATA_WRITE logging.
         */
        export interface AuditConfigResponse {
            /**
             * The configuration for logging of each type of permission.
             */
            auditLogConfigs: outputs.metastore.v1alpha.AuditLogConfigResponse[];
            /**
             * Specifies a service that will be enabled for audit logging. For example, storage.googleapis.com, cloudsql.googleapis.com. allServices is a special value that covers all services.
             */
            service: string;
        }

        /**
         * Provides the configuration for logging a type of permissions. Example: { "audit_log_configs": [ { "log_type": "DATA_READ", "exempted_members": [ "user:jose@example.com" ] }, { "log_type": "DATA_WRITE" } ] } This enables 'DATA_READ' and 'DATA_WRITE' logging, while exempting jose@example.com from DATA_READ logging.
         */
        export interface AuditLogConfigResponse {
            /**
             * Specifies the identities that do not cause logging for this type of permission. Follows the same format of Binding.members.
             */
            exemptedMembers: string[];
            /**
             * The log type that this config enables.
             */
            logType: string;
        }

        /**
         * Configuration information for the auxiliary service versions.
         */
        export interface AuxiliaryVersionConfigResponse {
            /**
             * A mapping of Hive metastore configuration key-value pairs to apply to the auxiliary Hive metastore (configured in hive-site.xml) in addition to the primary version's overrides. If keys are present in both the auxiliary version's overrides and the primary version's overrides, the value from the auxiliary version's overrides takes precedence.
             */
            configOverrides: {[key: string]: string};
            /**
             * The network configuration contains the endpoint URI(s) of the auxiliary Hive metastore service.
             */
            networkConfig: outputs.metastore.v1alpha.NetworkConfigResponse;
            /**
             * The Hive metastore version of the auxiliary service. It must be less than the primary Hive metastore service's version.
             */
            version: string;
        }

        /**
         * Represents a backend metastore for the federation.
         */
        export interface BackendMetastoreResponse {
            /**
             * The type of the backend metastore.
             */
            metastoreType: string;
            /**
             * The relative resource name of the metastore that is being federated. The formats of the relative resource names for the currently supported metastores are listed below: BigQuery projects/{project_id} Dataproc Metastore projects/{project_id}/locations/{location}/services/{service_id}
             */
            name: string;
        }

        /**
         * Associates members, or principals, with a role.
         */
        export interface BindingResponse {
            /**
             * The condition that is associated with this binding.If the condition evaluates to true, then this binding applies to the current request.If the condition evaluates to false, then this binding does not apply to the current request. However, a different role binding might grant the same role to one or more of the principals in this binding.To learn which resources support conditions in their IAM policies, see the IAM documentation (https://cloud.google.com/iam/help/conditions/resource-policies).
             */
            condition: outputs.metastore.v1alpha.ExprResponse;
            /**
             * Specifies the principals requesting access for a Google Cloud resource. members can have the following values: allUsers: A special identifier that represents anyone who is on the internet; with or without a Google account. allAuthenticatedUsers: A special identifier that represents anyone who is authenticated with a Google account or a service account. Does not include identities that come from external identity providers (IdPs) through identity federation. user:{emailid}: An email address that represents a specific Google account. For example, alice@example.com . serviceAccount:{emailid}: An email address that represents a Google service account. For example, my-other-app@appspot.gserviceaccount.com. serviceAccount:{projectid}.svc.id.goog[{namespace}/{kubernetes-sa}]: An identifier for a Kubernetes service account (https://cloud.google.com/kubernetes-engine/docs/how-to/kubernetes-service-accounts). For example, my-project.svc.id.goog[my-namespace/my-kubernetes-sa]. group:{emailid}: An email address that represents a Google group. For example, admins@example.com. domain:{domain}: The G Suite domain (primary) that represents all the users of that domain. For example, google.com or example.com. deleted:user:{emailid}?uid={uniqueid}: An email address (plus unique identifier) representing a user that has been recently deleted. For example, alice@example.com?uid=123456789012345678901. If the user is recovered, this value reverts to user:{emailid} and the recovered user retains the role in the binding. deleted:serviceAccount:{emailid}?uid={uniqueid}: An email address (plus unique identifier) representing a service account that has been recently deleted. For example, my-other-app@appspot.gserviceaccount.com?uid=123456789012345678901. If the service account is undeleted, this value reverts to serviceAccount:{emailid} and the undeleted service account retains the role in the binding. deleted:group:{emailid}?uid={uniqueid}: An email address (plus unique identifier) representing a Google group that has been recently deleted. For example, admins@example.com?uid=123456789012345678901. If the group is recovered, this value reverts to group:{emailid} and the recovered group retains the role in the binding.
             */
            members: string[];
            /**
             * Role that is assigned to the list of members, or principals. For example, roles/viewer, roles/editor, or roles/owner.
             */
            role: string;
        }

        /**
         * Contains information of the customer's network configurations.
         */
        export interface ConsumerResponse {
            /**
             * The location of the endpoint URI. Format: projects/{project}/locations/{location}.
             */
            endpointLocation: string;
            /**
             * The URI of the endpoint used to access the metastore service.
             */
            endpointUri: string;
            /**
             * Immutable. The subnetwork of the customer project from which an IP address is reserved and used as the Dataproc Metastore service's endpoint. It is accessible to hosts in the subnet and to all hosts in a subnet in the same region and same network. There must be at least one IP address available in the subnet's primary range. The subnet is specified in the following form:projects/{project_number}/regions/{region_id}/subnetworks/{subnetwork_id}
             */
            subnetwork: string;
        }

        /**
         * Specifies how metastore metadata should be integrated with the Data Catalog service.
         */
        export interface DataCatalogConfigResponse {
            /**
             * Optional. Defines whether the metastore metadata should be synced to Data Catalog. The default value is to disable syncing metastore metadata to Data Catalog.
             */
            enabled: boolean;
        }

        /**
         * A specification of the location of and metadata about a database dump from a relational database management system.
         */
        export interface DatabaseDumpResponse {
            /**
             * The type of the database.
             */
            databaseType: string;
            /**
             * A Cloud Storage object or folder URI that specifies the source from which to import metadata. It must begin with gs://.
             */
            gcsUri: string;
            /**
             * The name of the source database.
             */
            sourceDatabase: string;
            /**
             * Optional. The type of the database dump. If unspecified, defaults to MYSQL.
             */
            type: string;
        }

        /**
         * Specifies how metastore metadata should be integrated with the Dataplex service.
         */
        export interface DataplexConfigResponse {
            /**
             * A reference to the Lake resources that this metastore service is attached to. The key is the lake resource name. Example: projects/{project_number}/locations/{location_id}/lakes/{lake_id}.
             */
            lakeResources: {[key: string]: outputs.metastore.v1alpha.LakeResponse};
        }

        /**
         * Encryption settings for the service.
         */
        export interface EncryptionConfigResponse {
            /**
             * The fully qualified customer provided Cloud KMS key name to use for customer data encryption, in the following form:projects/{project_number}/locations/{location_id}/keyRings/{key_ring_id}/cryptoKeys/{crypto_key_id}.
             */
            kmsKey: string;
        }

        /**
         * Represents a textual expression in the Common Expression Language (CEL) syntax. CEL is a C-like expression language. The syntax and semantics of CEL are documented at https://github.com/google/cel-spec.Example (Comparison): title: "Summary size limit" description: "Determines if a summary is less than 100 chars" expression: "document.summary.size() < 100" Example (Equality): title: "Requestor is owner" description: "Determines if requestor is the document owner" expression: "document.owner == request.auth.claims.email" Example (Logic): title: "Public documents" description: "Determine whether the document should be publicly visible" expression: "document.type != 'private' && document.type != 'internal'" Example (Data Manipulation): title: "Notification string" description: "Create a notification string with a timestamp." expression: "'New message received at ' + string(document.create_time)" The exact variables and functions that may be referenced within an expression are determined by the service that evaluates it. See the service documentation for additional information.
         */
        export interface ExprResponse {
            /**
             * Optional. Description of the expression. This is a longer text which describes the expression, e.g. when hovered over it in a UI.
             */
            description: string;
            /**
             * Textual representation of an expression in Common Expression Language syntax.
             */
            expression: string;
            /**
             * Optional. String indicating the location of the expression for error reporting, e.g. a file name and a position in the file.
             */
            location: string;
            /**
             * Optional. Title for the expression, i.e. a short string describing its purpose. This can be used e.g. in UIs which allow to enter the expression.
             */
            title: string;
        }

        /**
         * Specifies configuration information specific to running Hive metastore software as the metastore service.
         */
        export interface HiveMetastoreConfigResponse {
            /**
             * A mapping of Hive metastore version to the auxiliary version configuration. When specified, a secondary Hive metastore service is created along with the primary service. All auxiliary versions must be less than the service's primary version. The key is the auxiliary service name and it must match the regular expression a-z?. This means that the first character must be a lowercase letter, and all the following characters must be hyphens, lowercase letters, or digits, except the last character, which cannot be a hyphen.
             */
            auxiliaryVersions: {[key: string]: outputs.metastore.v1alpha.AuxiliaryVersionConfigResponse};
            /**
             * A mapping of Hive metastore configuration key-value pairs to apply to the Hive metastore (configured in hive-site.xml). The mappings override system defaults (some keys cannot be overridden). These overrides are also applied to auxiliary versions and can be further customized in the auxiliary version's AuxiliaryVersionConfig.
             */
            configOverrides: {[key: string]: string};
            /**
             * The protocol to use for the metastore service endpoint. If unspecified, defaults to THRIFT.
             */
            endpointProtocol: string;
            /**
             * Information used to configure the Hive metastore service as a service principal in a Kerberos realm. To disable Kerberos, use the UpdateService method and specify this field's path (hive_metastore_config.kerberos_config) in the request's update_mask while omitting this field from the request's service.
             */
            kerberosConfig: outputs.metastore.v1alpha.KerberosConfigResponse;
            /**
             * Immutable. The Hive metastore schema version.
             */
            version: string;
        }

        /**
         * Configuration information for a Kerberos principal.
         */
        export interface KerberosConfigResponse {
            /**
             * A Kerberos keytab file that can be used to authenticate a service principal with a Kerberos Key Distribution Center (KDC).
             */
            keytab: outputs.metastore.v1alpha.SecretResponse;
            /**
             * A Cloud Storage URI that specifies the path to a krb5.conf file. It is of the form gs://{bucket_name}/path/to/krb5.conf, although the file does not need to be named krb5.conf explicitly.
             */
            krb5ConfigGcsUri: string;
            /**
             * A Kerberos principal that exists in the both the keytab the KDC to authenticate as. A typical principal is of the form primary/instance@REALM, but there is no exact format.
             */
            principal: string;
        }

        /**
         * Represents a Lake resource
         */
        export interface LakeResponse {
            /**
             * The Lake resource name. Example: projects/{project_number}/locations/{location_id}/lakes/{lake_id}
             */
            name: string;
        }

        /**
         * Maintenance window. This specifies when Dataproc Metastore may perform system maintenance operation to the service.
         */
        export interface MaintenanceWindowResponse {
            /**
             * The day of week, when the window starts.
             */
            dayOfWeek: string;
            /**
             * The hour of day (0-23) when the window starts.
             */
            hourOfDay: number;
        }

        /**
         * The details of a metadata export operation.
         */
        export interface MetadataExportResponse {
            /**
             * The type of the database dump.
             */
            databaseDumpType: string;
            /**
             * A Cloud Storage URI of a folder that metadata are exported to, in the form of gs:////, where is automatically generated.
             */
            destinationGcsUri: string;
            /**
             * The time when the export ended.
             */
            endTime: string;
            /**
             * The time when the export started.
             */
            startTime: string;
            /**
             * The current state of the export.
             */
            state: string;
        }

        /**
         * Specifies how metastore metadata should be integrated with external services.
         */
        export interface MetadataIntegrationResponse {
            /**
             * Optional. The integration config for the Data Catalog service.
             */
            dataCatalogConfig: outputs.metastore.v1alpha.DataCatalogConfigResponse;
            /**
             * The integration config for the Dataplex service.
             */
            dataplexConfig: outputs.metastore.v1alpha.DataplexConfigResponse;
        }

        /**
         * The metadata management activities of the metastore service.
         */
        export interface MetadataManagementActivityResponse {
            /**
             * The latest metadata exports of the metastore service.
             */
            metadataExports: outputs.metastore.v1alpha.MetadataExportResponse[];
            /**
             * The latest restores of the metastore service.
             */
            restores: outputs.metastore.v1alpha.RestoreResponse[];
        }

        /**
         * Network configuration for the Dataproc Metastore service.
         */
        export interface NetworkConfigResponse {
            /**
             * Immutable. The consumer-side network configuration for the Dataproc Metastore instance.
             */
            consumers: outputs.metastore.v1alpha.ConsumerResponse[];
            /**
             * Enables custom routes to be imported and exported for the Dataproc Metastore service's peered VPC network.
             */
            customRoutesEnabled: boolean;
        }

        /**
         * The details of a metadata restore operation.
         */
        export interface RestoreResponse {
            /**
             * The relative resource name of the metastore service backup to restore from, in the following form:projects/{project_id}/locations/{location_id}/services/{service_id}/backups/{backup_id}.
             */
            backup: string;
            /**
             * Optional. A Cloud Storage URI specifying where the backup artifacts are stored, in the format gs:///.
             */
            backupLocation: string;
            /**
             * The restore details containing the revision of the service to be restored to, in format of JSON.
             */
            details: string;
            /**
             * The time when the restore ended.
             */
            endTime: string;
            /**
             * The time when the restore started.
             */
            startTime: string;
            /**
             * The current state of the restore.
             */
            state: string;
            /**
             * The type of restore.
             */
            type: string;
        }

        /**
         * Represents the scaling configuration of a metastore service.
         */
        export interface ScalingConfigResponse {
            /**
             * An enum of readable instance sizes, with each instance size mapping to a float value (e.g. InstanceSize.EXTRA_SMALL = scaling_factor(0.1))
             */
            instanceSize: string;
            /**
             * Scaling factor, increments of 0.1 for values less than 1.0, and increments of 1.0 for values greater than 1.0.
             */
            scalingFactor: number;
        }

        /**
         * A securely stored value.
         */
        export interface SecretResponse {
            /**
             * The relative resource name of a Secret Manager secret version, in the following form:projects/{project_number}/secrets/{secret_id}/versions/{version_id}.
             */
            cloudSecret: string;
        }

        /**
         * A managed metastore service that serves metadata queries.
         */
        export interface ServiceResponse {
            /**
             * A Cloud Storage URI (starting with gs://) that specifies where artifacts related to the metastore service are stored.
             */
            artifactGcsUri: string;
            /**
             * The time when the metastore service was created.
             */
            createTime: string;
            /**
             * Immutable. The database type that the Metastore service stores its data.
             */
            databaseType: string;
            /**
             * Immutable. Information used to configure the Dataproc Metastore service to encrypt customer data at rest. Cannot be updated.
             */
            encryptionConfig: outputs.metastore.v1alpha.EncryptionConfigResponse;
            /**
             * The URI of the endpoint used to access the metastore service.
             */
            endpointUri: string;
            /**
             * Configuration information specific to running Hive metastore software as the metastore service.
             */
            hiveMetastoreConfig: outputs.metastore.v1alpha.HiveMetastoreConfigResponse;
            /**
             * User-defined labels for the metastore service.
             */
            labels: {[key: string]: string};
            /**
             * The one hour maintenance window of the metastore service. This specifies when the service can be restarted for maintenance purposes in UTC time. Maintenance window is not needed for services with the SPANNER database type.
             */
            maintenanceWindow: outputs.metastore.v1alpha.MaintenanceWindowResponse;
            /**
             * Optional. The setting that defines how metastore metadata should be integrated with external services and systems.
             */
            metadataIntegration: outputs.metastore.v1alpha.MetadataIntegrationResponse;
            /**
             * The metadata management activities of the metastore service.
             */
            metadataManagementActivity: outputs.metastore.v1alpha.MetadataManagementActivityResponse;
            /**
             * Immutable. The relative resource name of the metastore service, in the following format:projects/{project_number}/locations/{location_id}/services/{service_id}.
             */
            name: string;
            /**
             * Immutable. The relative resource name of the VPC network on which the instance can be accessed. It is specified in the following form:projects/{project_number}/global/networks/{network_id}.
             */
            network: string;
            /**
             * The configuration specifying the network settings for the Dataproc Metastore service.
             */
            networkConfig: outputs.metastore.v1alpha.NetworkConfigResponse;
            /**
             * The TCP port at which the metastore service is reached. Default: 9083.
             */
            port: number;
            /**
             * Immutable. The release channel of the service. If unspecified, defaults to STABLE.
             */
            releaseChannel: string;
            /**
             * Scaling configuration of the metastore service.
             */
            scalingConfig: outputs.metastore.v1alpha.ScalingConfigResponse;
            /**
             * The current state of the metastore service.
             */
            state: string;
            /**
             * Additional information about the current state of the metastore service, if available.
             */
            stateMessage: string;
            /**
             * The configuration specifying telemetry settings for the Dataproc Metastore service. If unspecified defaults to JSON.
             */
            telemetryConfig: outputs.metastore.v1alpha.TelemetryConfigResponse;
            /**
             * The tier of the service.
             */
            tier: string;
            /**
             * The globally unique resource identifier of the metastore service.
             */
            uid: string;
            /**
             * The time when the metastore service was last updated.
             */
            updateTime: string;
        }

        /**
         * Telemetry Configuration for the Dataproc Metastore service.
         */
        export interface TelemetryConfigResponse {
            /**
             * The output format of the Dataproc Metastore service's logs.
             */
            logFormat: string;
        }

    }

